/**
 * Seed question bank: curriculum-aligned items for every Class XII learning outcome
 * (SCF 2022 Tables 16-20 / Physics IG 2022). Every item carries: correct answer, detailed
 * explanation, common misconception, three graduated hints, and worked steps for numericals.
 * IG exemplar questions informed the contexts; numbers were changed so items are not copies.
 */
import type { QuestionInput } from "../src/lib/questions";

type B = QuestionInput["bloom"];
interface F { e: string; m: string; h: [string, string, string]; s?: string[]; d?: number; dom?: "SK" | "WS" | "SV"; marks?: number }
const base = (code: string, sub: string, bloom: B, stem: string, f: F) => ({
  outcomeCode: `XII.${code}`, subtopicNumber: sub, bloom, stem, explanation: f.e, misconception: f.m, hints: f.h,
  solutionSteps: f.s ?? [], difficulty: f.d ?? 2, domain: f.dom ?? "SK", marks: f.marks ?? 1, scopeNote: null,
});
const mcq = (c: string, sub: string, b: B, stem: string, options: string[], index: number, f: F): QuestionInput => ({ ...base(c, sub, b, stem, f), type: "MCQ", payload: { options }, answer: { index } });
const tf = (c: string, sub: string, b: B, stem: string, value: boolean, f: F): QuestionInput => ({ ...base(c, sub, b, stem, f), type: "TRUE_FALSE", payload: {}, answer: { value } });
const fill = (c: string, sub: string, b: B, stem: string, blanks: string[][], f: F): QuestionInput => ({ ...base(c, sub, b, stem, f), type: "FILL_BLANK", payload: {}, answer: { blanks } });
/** right[] is written in matching order; pairs are derived so the stored right column is reversed (not answer order). */
const match = (c: string, sub: string, b: B, stem: string, left: string[], right: string[], f: F): QuestionInput => {
  const shuffled = [...right].reverse();
  return { ...base(c, sub, b, stem, f), type: "MATCHING", payload: { left, right: shuffled }, answer: { pairs: left.map((_, i) => shuffled.indexOf(right[i])) } };
};
const num = (c: string, sub: string, b: B, stem: string, value: number, unit: string, f: F & { s: string[] }, tolerancePct = 2): QuestionInput => ({ ...base(c, sub, b, stem, f), type: "NUMERICAL", payload: { unit }, answer: { value, tolerancePct } });
const ar = (c: string, sub: string, b: B, assertion: string, reason: string, index: number, f: F): QuestionInput => ({ ...base(c, sub, b, "Read the Assertion (A) and the Reason (R), then choose the correct option.", f), type: "ASSERTION_REASON", payload: { assertion, reason }, answer: { index } });
const essay = (c: string, sub: string, b: B, stem: string, keyPoints: string[], modelAnswer: string, f: F): QuestionInput => ({ ...base(c, sub, b, stem, { marks: 3, ...f }), type: "CONCEPTUAL", payload: { keyPoints }, answer: { modelAnswer } });

